<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_api_notification_state( WP_REST_Request $request ) { if ( ! is_user_logged_in() || ! sd_core_notifications_available() ) { return new WP_Error( 'notifications_unavailable', __( 'Notifications are unavailable.', 'social-discovery-core' ), array( 'status' => 503 ) ); } $action = sanitize_key( $request->get_param( 'action' ) ); if ( 'all-read' === $action && function_exists( 'bp_notifications_mark_all_for_user' ) ) { return rest_ensure_response( array( 'updated' => (bool) bp_notifications_mark_all_for_user( get_current_user_id() ) ) ); } $result = sd_core_notification_action( absint( $request->get_param( 'notification_id' ) ), $action ); return is_wp_error( $result ) ? $result : rest_ensure_response( array( 'updated' => (bool) $result ) ); }
